int git_pkt_parse(git_pkt **head, const char *line, const char **out, size_t bufflen) {
    const char *start = line;
    size_t linelen = 0;

    if (!line || !head || !out || bufflen < 4)
        return GIT_EBUFS;

    /* Check if the buffer has enough space to read the packet length */
    if (bufflen < 4) {
        return GIT_EBUFS;
    }

    linelen = (unsigned char)line[0] << 24 |
              (unsigned char)line[1] << 16 |
              (unsigned char)line[2] << 8  |
              (unsigned char)line[3];

    if (linelen > (bufflen - 4)) {
        return GIT_EBUFS;
    }

    /* Allocate memory for the packet */
    *head = calloc(1, sizeof(git_pkt));
    if (!*head) {
        return GIT_ERROR;
    }

    (*head)->data = (char *)malloc(linelen + 1);
    if (!(*head)->data) {
        free(*head);
        *head = NULL;
        return GIT_ERROR;
    }

    /* Copy packet data */
    memcpy((*head)->data, line + 4, linelen);
    (*head)->data[linelen] = '\0'; /* Null-terminate the string */

    /* Process packet type */
    if (strncmp((*head)->data, "data", 4) == 0) {
        if (git_pkt_handle_data(*head) < 0) {
            git_pkt_free(*head);
            *head = NULL;
            return GIT_ERROR;
        }
    } else if (strncmp((*head)->data, "sideband", 8) == 0) {
        if (git_pkt_handle_sideband(*head) < 0) {
            git_pkt_free(*head);
            *head = NULL;
            return GIT_ERROR;
        }
    } else if (strncmp((*head)->data, "ACK", 3) == 0) {
        if (git_pkt_handle_ack(*head) < 0) {
            git_pkt_free(*head);
            *head = NULL;
            return GIT_ERROR;
        }
    } else if (strncmp((*head)->data, "FLUSH", 5) == 0) {
        git_pkt_handle_flush(*head);
    } else {
        git_pkt_free(*head);
        *head = NULL;
        return GIT_ERROR;
    }

    *out = line + 4 + linelen;

    return 0;
}

int git_pkt_parse_line(git_pkt **head, const char *line, const char **out, size_t bufflen) {
    if (bufflen < 4)
        return GIT_EBUFS;

    if (!strncmp(line, "data", 4)) {
        size_t len = 0;
        if (sscanf(line + 4, "%zu", &len) != 1)
            return GIT_ERROR;

        if (len > (bufflen - 4))
            return GIT_EBUFS;

        *head = git_pkt_new(GIT_PKT_DATA);
        if (!*head)
            return GIT_ERROR;

        if (git_pkt_set_data(*head, line + 4, len) < 0)
            return GIT_ERROR;

        *out = line + 4 + len;
        return 0;
    } else if (!strncmp(line, "ACK", 3)) {
        *head = git_pkt_new(GIT_PKT_ACK);
        if (!*head)
            return GIT_ERROR;

        *out = line + 3;
        return 0;
    } else if (!strncmp(line, "FLUSH", 5)) {
        *head = git_pkt_new(GIT_PKT_FLUSH);
        if (!*head)
            return GIT_ERROR;

        *out = line + 5;
        return 0;
    } else if (!strncmp(line, "SIDEBAND", 8)) {
        int channel = 0;
        if (sscanf(line + 8, "%d", &channel) != 1 || channel < 0)
            return GIT_ERROR;

        if (channel >= 3)
            return GIT_ERROR;

        *head = git_pkt_new(GIT_PKT_SIDEBAND);
        if (!*head)
            return GIT_ERROR;

        if (git_pkt_set_sideband_channel(*head, channel) < 0)
            return GIT_ERROR;

        *out = line + 8;
        return 0;
    } else {
        return GIT_ERROR;
    }
}

int git_pkt_parse_line(git_pkt **head, const char *line, const char **out, size_t bufflen) {
    if (bufflen < 4) {
        return GIT_EBUFS;
    }

