        git_pkt *pkt = calloc(1, sizeof(git_pkt));
        if (!pkt) {
            return GIT_ERROR;
        }

        pkt->type = GIT_PKT_DATA;
        pkt->data = strdup(line);
        if (!pkt->data) {
            free(pkt);
            return GIT_ERROR;
        }

        *head = pkt;
        *out = line + strlen(line) + 1;
        return 0;
