int parse_pkt_line(git_pkt **head, const char *line, const char **out, size_t bufflen) {
    if (bufflen < 4) {
        return GIT_EBUFS;
    }

    if (!strncmp(line, "0000", 4)) {
        *out = line + 4;
        return 0;
    }

    size_t pkt_len = 0;
    if (sscanf(line, "%04zx", &pkt_len) != 1) {
        return GIT_ERROR;
    }

    if (pkt_len < 4) {
        return GIT_ERROR;
    }

    if (bufflen < pkt_len) {
        return GIT_EBUFS;
    }

    if (!strncmp(line + 4, "ACK", 3)) {
        if (process_ack_pkt(head, line + 4, bufflen - 4)) {
            return GIT_ERROR;
        }
    } else if (!strncmp(line + 4, "NAK", 3)) {
        if (process_nak_pkt(head, line + 4, bufflen - 4)) {
            return GIT_ERROR;
        }
    } else if (!strncmp(line + 4, "SIDEBAND", 8)) {
        if (process_sideband_pkt(head, line + 4, bufflen - 4)) {
            return GIT_ERROR;
        }
    } else if (!strncmp(line + 4, "FLUSH", 5)) {
        if (process_flush_pkt(head, line + 4, bufflen - 4)) {
            return GIT_ERROR;
        }
    } else {
        if (process_data_pkt(head, line + 4, bufflen - 4)) {
            return GIT_ERROR;
        }
    }

    *out = line + pkt_len;
    return 0;
}

int git_pkt_parse_line(git_pkt **head, const char *line, const char **out, size_t bufflen) {
    if (bufflen < 4) {
        return GIT_EBUFS;
    }

    size_t len;
    if (sscanf(line, "%4" SCNuMAX, &len) != 1) {
        return GIT_ERROR;
    }

    if (len > bufflen) {
        return GIT_EBUFS;
    }

    if (strncmp(line + 4, "data", 4) == 0) {
        return git_pkt_handle_data(head, line + 8, len - 4);
    } else if (strncmp(line + 4, "sideband", 8) == 0) {
        return git_pkt_handle_sideband(head, line + 12, len - 8);
    } else if (strncmp(line + 4, "ACK", 3) == 0) {
        return git_pkt_handle_ack(head, line + 7, len - 4);
    } else if (strncmp(line + 4, "flush", 5) == 0) {
        git_pkt_flush(head);
    } else {
        return GIT_ERROR;
    }

    *out = line + len;
    return 0;
}
